class Manager:
    def hash_password(self, passphrase):
        return bcrypt.hashpw(passphrase.encode(), bcrypt.gensalt())

    def parse_args(self):
        parser = argparse.ArgumentParser()
        parser.add_argument("--input")
        return parser.parse_args()

    def encrypt_note(self, aes_key, note):
        cipher = AES.new(aes_key, AES.MODE_GCM)
        ct, tag = cipher.encrypt_and_digest(note)
        return cipher.nonce + tag + ct

    def encrypt_data(self, master_key, data):
        iv = get_random_bytes(16)
        cipher = AES.new(master_key, AES.MODE_CBC, iv)
        return iv + cipher.encrypt(pad(data, AES.block_size))

